// Monodromy-equivariant Hom between the two rank-one mixed-variation lines.

fn main() {
    // Contact mixed image is generated by 1 and is invariant around both walls.
    let contact = [1_i32, 1_i32];
    // The lower line sqrt(nu_i nu_j) changes sign around either labelled wall.
    let lower = [-1_i32, -1_i32];

    // A scalar map h must satisfy lower[k] h = h contact[k].  Over Q this
    // forces h=0 as soon as one character differs.
    let coefficients = [lower[0] - contact[0], lower[1] - contact[1]];
    assert_eq!(coefficients, [-2, -2]);
    let hom_dimension = usize::from(coefficients.iter().all(|x| *x == 0));
    assert_eq!(hom_dimension, 0);

    // The unique correcting character is the labelled half-Kummer character.
    let required_twist = [lower[0] * contact[0], lower[1] * contact[1]];
    assert_eq!(required_twist, [-1, -1]);

    println!(
        "{{\"status\":\"pass\",\"contact_character\":[1,1],\"lower_character\":[-1,-1],\"equivariant_hom_dimension\":0,\"required_twist\":[-1,-1]}}"
    );
}
